  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision measurement, enabling stringent tests of fundamental physics and a new level of timekeeping. The achievement is exceptionally important and has clear experimental consequences.",
        "attribution": "Katori and Ye made distinct, complementary contributions to the clock concept and its realization; the proposed attribution is focused and credible.",
        "maturity": "The clocks have been developed and validated over many years, with precision and applications continuing to advance. The discovery is mature.",
        "uncertainties": [
          "The boundary between the original invention and later advances in clock performance may need careful treatment."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Michel Della Negra",
        "Peter Jenni",
        "Tejinder Virdee"
      ],
      "assessment": {
        "nobel_worthiness": "The ATLAS and CMS detectors made possible the experimental discovery of the Higgs boson, a landmark confirmation of a central part of the Standard Model. The scientific importance is beyond serious doubt.",
        "attribution": "These detector leaders represent substantial contributions to the experiments, but the discovery depended on very large collaborations. The attribution question is unusually difficult for a prize limited to a few people.",
        "maturity": "The Higgs signal has been confirmed and its properties measured across many years of LHC data. The result is firmly established.",
        "uncertainties": [
          "How to recognize the essential work of large experimental collaborations within the individual laureate limit."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Francis Halzen"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube opened a new window on the high-energy universe by establishing astrophysical neutrinos as observable messengers. This is a major advance in both astronomy and particle physics.",
        "attribution": "Halzen's leadership and contribution to the observatory are central, though the result rests on the work of a large collaboration and a long program of detector development.",
        "maturity": "The astrophysical neutrino flux is established and the field has progressed to identifying sources. The discovery is mature, while the full source picture remains under development.",
        "uncertainties": [
          "The extent to which the discovery should be credited to an individual rather than the IceCube collaboration."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precise mapping of the cosmic microwave background established key parameters of the standard cosmological model and made precision cosmology possible. The result has enduring scientific impact.",
        "attribution": "Bennett and Page represent leadership in the mission and its measurements; Spergel helped connect the data to cosmological interpretation. The contribution spans both instrument and analysis.",
        "maturity": "The measurements have been tested against later observations, including Planck, and remain foundational. The scientific result is mature.",
        "uncertainties": [
          "The contribution relative to COBE's earlier landmark CMB measurements and subsequent missions requires careful delineation."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Jean Dalibard",
        "Juan Ignacio Cirac"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices provide controlled experimental access to quantum many-body systems that are difficult to study otherwise. This is a powerful new method with broad value for fundamental physics.",
        "attribution": "Bloch and Dalibard are central to the experimental realization and development; Cirac contributed key theoretical foundations. The field is collaborative, and the proposed trio captures complementary roles.",
        "maturity": "The platform has produced important results over decades and continues to improve. Its full reach as a simulator of complex materials is still being established.",
        "uncertainties": [
          "The breadth of the discovery and the number of influential contributors make the most faithful attribution uncertain."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and experimental realization of topological insulators and the quantum spin Hall effect revealed a new class of quantum matter and reshaped condensed matter physics.",
        "attribution": "Kane and Mele established the theoretical framework, while Molenkamp's experiments provided an early realization of the quantum spin Hall effect. The theory and experiment are appropriately paired.",
        "maturity": "The phases have been observed and characterized in multiple materials, and the topological framework is well established. Applications remain less mature than the fundamental discovery.",
        "uncertainties": [
          "The proposed credit centers on an early material realization; the role of subsequent experiments in establishing the broader class merits review."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B048",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction made clear how quantum information can be protected despite noise and laid the conceptual foundation for fault-tolerant quantum computation. Its impact is deep and potentially far-reaching.",
        "attribution": "Kitaev, Steane, and Shor made foundational, identifiable contributions to codes and fault-tolerance theory. The proposed group reflects central theoretical advances.",
        "maturity": "The theoretical framework is mature, while large-scale fault-tolerant operation remains an active experimental goal. Recognition of the principle is separable from completion of the technology.",
        "uncertainties": [
          "The breadth of later contributions and the continuing evolution of demonstrations complicate the boundary of the discovery."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and Berry phase exposed the physical importance of quantum phases and geometric structure, with consequences across many areas of physics.",
        "attribution": "Aharonov is associated with the prediction of the Aharonov-Bohm effect, and Berry with the general geometric phase. The two contributions are distinct and identifiable.",
        "maturity": "Both effects have extensive theoretical and experimental confirmation and are deeply integrated into modern physics. The work is fully mature.",
        "uncertainties": [
          "The umbrella description combines two discoveries from different periods, so the scope and balance of the proposed recognition need definition."
        ]
      }
    }
  ]
}
